fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: task [add|list|done|remove] [args...]");
        process::exit(1);
    }

    let mut manager = TaskManager::new();
    manager.load().unwrap_or_else(|e| eprintln!("Warning: {}", e));

    match args[1].as_str() {
        "add" => {
            if args.len() < 3 {
                eprintln!("Usage: task add <description>");
                process::exit(1);
            }
            let desc = args[2..].join(" ");
            manager.add(desc);
            manager.save().unwrap();
            println!("Task added!");
        }
        "list" => manager.list(),
        "done" => {
            if args.len() < 3 {
                eprintln!("Usage: task done <id>");
                process::exit(1);
            }
            let id: usize = args[2].parse().unwrap_or_else(|_| {
                eprintln!("Invalid id");
                process::exit(1);
            });
            manager.complete(id);
            manager.save().unwrap();
        }
        _ => eprintln!("Unknown command"),
    }
}

